{
  "name": "AI Sales Assistant Bot",
  "description": "An AI-powered auto-responder that transcribes messages and instantly answers customer questions via a chat interface, using pre-trained sales templates to sell courses and services.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Message, Role } from './types';
import { getBotResponse } from './services/geminiService';
import { BOT_NAME, INITIAL_MESSAGE } from './constants';
import ChatHeader from './components/ChatHeader';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([INITIAL_MESSAGE]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading]);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!text.trim()) return;

    const userMessage: Message = { role: Role.USER, content: text };
    setMessages((prev) => [...prev, userMessage]);
    setIsLoading(true);
    setError(null);

    try {
      const botResponse = await getBotResponse(text, messages);
      const botMessage: Message = { role: Role.BOT, content: botResponse };
      setMessages((prev) => [...prev, botMessage]);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'An unknown error occurred.';
      setError(`Ошибка: ${errorMessage}`);
      const errorBotMessage: Message = { role: Role.BOT, content: `Извините, произошла ошибка. Попробуйте еще раз. (${errorMessage})` };
      setMessages((prev) => [...prev, errorBotMessage]);
    } finally {
      setIsLoading(false);
    }
  }, [messages]);

  const handleStartRecording = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaRecorderRef.current = new MediaRecorder(stream);
      audioChunksRef.current = [];

      mediaRecorderRef.current.ondataavailable = (event) => {
        audioChunksRef.current.push(event.data);
      };

      mediaRecorderRef.current.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        // In a real app, you would send this blob to a speech-to-text API.
        // Here, we simulate transcription and send a predefined prompt.
        const simulatedTranscription = "Здравствуйте, расскажите подробнее о ваших курсах.";
        const userMessage: Message = { role: Role.USER, content: "[Аудиосообщение] " + simulatedTranscription };
        setMessages((prev) => [...prev, userMessage]);
        handleSendMessage(simulatedTranscription);
        stream.getTracks().forEach(track => track.stop()); // Stop microphone access
      };

      mediaRecorderRef.current.start();
      setIsRecording(true);
    } catch (err) {
      console.error("Error accessing microphone:", err);
      setError("Не удалось получить доступ к микрофону. Пожалуйста, проверьте разрешения.");
    }
  }, [handleSendMessage]);

  const handleStopRecording = useCallback(() => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  }, []);

  return (
    <div className="flex justify-center items-center h-screen bg-gray-900 p-2 sm:p-4">
      <div className="flex flex-col w-full max-w-2xl h-full sm:h-[95vh] max-h-[800px] bg-gray-800 shadow-2xl rounded-2xl border border-gray-700">
        <ChatHeader botName={BOT_NAME} />
        <div className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-4">
          {messages.map((msg, index) => (
            <ChatMessage key={index} message={msg} />
          ))}
          {isLoading && <ChatMessage message={{ role: Role.BOT, content: '...' }} isLoading={true} />}
          {error && <div className="text-red-400 text-center text-sm py-2">{error}</div>}
          <div ref={chatEndRef} />
        </div>
        <ChatInput
          onSendMessage={handleSendMessage}
          isLoading={isLoading}
          isRecording={isRecording}
          onStartRecording={handleStartRecording}
          onStopRecording={handleStopRecording}
        />
      </div>
    </div>
  );
};

export default App;

export enum Role {
  USER = 'user',
  BOT = 'bot',
}

export interface Message {
  role: Role;
  content: string;
}

import { Message, Role } from './types';

export const BOT_NAME = "AI Sales Assistant";
export const BOT_STATUS = "Online";

export const INITIAL_MESSAGE: Message = {
  role: Role.BOT,
  content: "Здравствуйте! Я ваш персональный AI ассистент. Чем могу помочь? Я могу рассказать о наших курсах, услугах и специальных предложениях.",
};

export const SALES_INFO = `
Информация о продуктах:
- Курс "React для Начинающих": Стоимость - 10,000 руб. Длительность - 4 недели. Включает видео-уроки, домашние задания и поддержку куратора.
- Курс "Продвинутый TypeScript": Стоимость - 15,000 руб. Длительность - 6 недель. Для тех, кто уже знаком с JavaScript. Глубокое погружение в типы, дженерики и продвинутые паттерны.
- Услуга "Карьерная Консультация": Стоимость - 5,000 руб/час. Помогаем составить резюме, подготовиться к собеседованию и разработать карьерный план.
- Скидка: При покупке двух курсов сразу - скидка 15%.

Шаблоны продаж:
- Приветствие: "Здравствуйте! Рад помочь вам. Какой из наших продуктов вас интересует?"
- Выявление потребностей: "Чтобы я мог подобрать для вас лучшее решение, расскажите, пожалуйста, какие у вас цели?"
- Презентация продукта: "Отличный выбор! Наш курс 'React для Начинающих' идеально подходит для старта в веб-разработке. Вы научитесь..."
- Работа с возражениями (дорого): "Я понимаю. Инвестиции в образование - это важный шаг. Наши курсы окупаются в среднем за 2-3 месяца после трудоустройства. К тому же, у нас есть возможность рассрочки."
- Призыв к действию: "Готовы начать обучение? Могу выслать вам ссылку на оплату."
`;

export const SYSTEM_INSTRUCTION = `
Вы — дружелюбный и высокоэффективный бот-помощник по продажам по имени ${BOT_NAME}.
Ваша главная цель — продавать курсы и услуги, предоставляя клиентам исчерпывающую информацию и помогая им сделать выбор.
Всегда будьте вежливы, позитивны и нацелены на результат.
Используйте информацию о продуктах и шаблоны продаж, чтобы строить свои ответы.
Не придумывайте информацию, которой нет в предоставленных данных.
Отвечайте на русском языке.
${SALES_INFO}
`;

import { GoogleGenAI, Chat } from "@google/genai";
import { Message, Role } from '../types';
import { SYSTEM_INSTRUCTION } from '../constants';

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

const chat: Chat = ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
    },
});

export const getBotResponse = async (prompt: string, history: Message[]): Promise<string> => {
  try {
    // Note: The current implementation of this simple chat does not pass full history
    // because the `ai.chats.create` with system instruction already maintains context.
    // For more complex scenarios, you might need to manage history more explicitly.
    const response = await chat.sendMessage({ message: prompt });

    if (response.text) {
      return response.text;
    }

    return "Я не совсем понимаю. Можете перефразировать?";
  } catch (error) {
    console.error("Gemini API error:", error);
    return "Произошла ошибка при обработке вашего запроса. Пожалуйста, попробуйте позже.";
  }
};

import React from 'react';
import { BOT_STATUS } from '../constants';

interface ChatHeaderProps {
  botName: string;
}

const ChatHeader: React.FC<ChatHeaderProps> = ({ botName }) => {
  return (
    <div className="bg-gray-700/50 p-4 border-b border-gray-600/50 flex items-center space-x-4 rounded-t-2xl">
      <div className="relative">
        <div className="w-12 h-12 rounded-full bg-gradient-to-br from-cyan-500 to-blue-600 flex items-center justify-center text-white font-bold text-xl">
          AI
        </div>
        <span className="absolute bottom-0 right-0 block h-3 w-3 rounded-full bg-green-400 border-2 border-gray-700"></span>
      </div>
      <div>
        <h1 className="text-lg font-bold text-white">{botName}</h1>
        <p className="text-sm text-green-400">{BOT_STATUS}</p>
      </div>
    </div>
  );
};

export default ChatHeader;

import React from 'react';
import { Message, Role } from '../types';

interface ChatMessageProps {
  message: Message;
  isLoading?: boolean;
}

const ChatMessage: React.FC<ChatMessageProps> = ({ message, isLoading = false }) => {
  const isBot = message.role === Role.BOT;

  const containerClasses = `flex items-end ${isBot ? 'justify-start' : 'justify-end'}`;
  const bubbleClasses = `px-4 py-3 rounded-2xl max-w-xs md:max-w-md lg:max-w-lg break-words ${
    isBot 
      ? 'bg-gray-700 text-white rounded-bl-none' 
      : 'bg-blue-600 text-white rounded-br-none'
  }`;

  const TypingIndicator = () => (
    <div className="flex items-center space-x-1.5">
      <div className="w-2 h-2 bg-gray-400 rounded-full animate-pulse [animation-delay:-0.3s]"></div>
      <div className="w-2 h-2 bg-gray-400 rounded-full animate-pulse [animation-delay:-0.15s]"></div>
      <div className="w-2 h-2 bg-gray-400 rounded-full animate-pulse"></div>
    </div>
  );

  return (
    <div className={containerClasses}>
      {isBot && (
        <div className="w-8 h-8 rounded-full bg-gradient-to-br from-cyan-500 to-blue-600 flex-shrink-0 mr-3 flex items-center justify-center text-white text-xs font-bold">
          AI
        </div>
      )}
      <div className={bubbleClasses} style={{ whiteSpace: 'pre-wrap' }}>
        {isLoading ? <TypingIndicator /> : message.content}
      </div>
    </div>
  );
};

export default ChatMessage;

import React, { useState } from 'react';
import MicIcon from './icons/MicIcon';
import SendIcon from './icons/SendIcon';
import StopIcon from './icons/StopIcon';

interface ChatInputProps {
  onSendMessage: (text: string) => void;
  isLoading: boolean;
  isRecording: boolean;
  onStartRecording: () => void;
  onStopRecording: () => void;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading, isRecording, onStartRecording, onStopRecording }) => {
  const [text, setText] = useState('');

  const handleSend = () => {
    if (text.trim() && !isLoading) {
      onSendMessage(text);
      setText('');
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      handleSend();
    }
  };

  const handleRecordToggle = () => {
    if (isRecording) {
      onStopRecording();
    } else {
      onStartRecording();
    }
  }

  return (
    <div className="bg-gray-700/50 p-4 border-t border-gray-600/50 rounded-b-2xl">
      <div className="flex items-center bg-gray-900/50 rounded-full px-4 py-2">
        {isRecording ? (
          <div className="flex items-center w-full">
            <div className="flex items-center text-red-500">
              <span className="relative flex h-3 w-3 mr-2">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-3 w-3 bg-red-500"></span>
              </span>
              Запись...
            </div>
            <div className="flex-grow text-center text-gray-400">
              Говорите в микрофон
            </div>
          </div>
        ) : (
          <input
            type="text"
            value={text}
            onChange={(e) => setText(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder="Введите ваше сообщение..."
            className="flex-1 bg-transparent text-white placeholder-gray-400 focus:outline-none disabled:opacity-50"
            disabled={isLoading}
          />
        )}
        <button
          onClick={text.trim() && !isRecording ? handleSend : handleRecordToggle}
          disabled={isLoading && !isRecording}
          className="ml-4 p-2 rounded-full transition-colors duration-200 ease-in-out focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50"
          aria-label={isRecording ? "Stop recording" : (text.trim() ? "Send message" : "Start recording")}
        >
          {isRecording ? (
            <div className="bg-red-500 hover:bg-red-600 p-2 rounded-full">
              <StopIcon />
            </div>
          ) : text.trim() ? (
            <div className="bg-blue-600 hover:bg-blue-700 p-2 rounded-full">
              <SendIcon />
            </div>
          ) : (
            <div className="bg-gray-600 hover:bg-gray-500 p-2 rounded-full">
              <MicIcon />
            </div>
          )}
        </button>
      </div>
    </div>
  );
};

export default ChatInput;

