const generateSalesInfo = (products: Product[]): string => {
  let info = 'Өнімдер туралы ақпарат:\n\n';
  products.forEach(p => {
    info += `- ${p.name.startsWith("Курс") ? '' : (p.duration.includes('сағат') ? 'Қызмет' : 'Курс')} "${p.name}":\n`;
    info += `  - Бағасы: ${p.price}.\n`;
    info += `  - Ұзақтығы: ${p.duration}.\n`;
    info += `  - Сипаттамасы: ${p.description}\n`;
    info += `  - Бұл курс кімге арналған: ${p.whoIsItFor}\n`;
    info += `  - Не үйренесіз: ${p.whatYouWillLearn}\n`;
    info += `  - Толық төлем сілтемесі: ${p.paymentLink}\n`;
    if (p.installmentLink) {
      info += `  - Бөліп төлеу (3 ай, пайызсыз): ${p.installmentLink}\n`;
    }
    info += '\n';
  });

  info += `- Арнайы шарттар:\n`;
  info += `  - Жеңілдік: Бірден екі курс сатып алғанда - 15% жеңілдік.\n`;
  info += `  - Бөліп төлеу: Бағасы 40,000 теңгеден (немесе 10,000 руб) жоғары барлық курстарға 3 айға пайызсыз бөліп төлеу мүмкіндігі бар.\n\n`;

  info += `Сату үлгілері:\n\n` +
  `- Сәлемдесу: "Сәлеметсіз бе! Мен курстар бойынша AI-кеңесшімін. IT саласындағы мақсаттарыңызға жетуге көмектесу үшін, неден бастағыңыз келетінін айтыңызшы?"\n\n` +
  `- Қажеттіліктерді анықтау:\n` +
  `  - "Программалауда қазіргі тәжірибеңіз қандай?"\n` +
  `  - "Сіздің соңғы мақсатыңыз қандай - алғашқы жұмыс табу, біліктілікті арттыру немесе өз жобаңызды құру ма?"\n` +
  `  - "Курс таңдауда сіз үшін ең маңыздысы не?"\n\n` +
  `- Өнімді таныстыру (қажеттіліктер негізінде): "Рахмет! Сіздің мақсаттарыңызға сүйене отырып, 'Вайбкодинг' курсы сіз үшін ең жақсы бастама болады. Сіз тек достық атмосферада негіздерді үйреніп қана қоймай, жұмысқа орналасу мүмкіндігіңізді күрт арттыратын алғашқы портфолиоңызды жасайсыз."\n\n` +
  `- Қарсылықтармен жұмыс:\n` +
  `  - Баға ("Бұл қымбат"): "Бағаның маңызды фактор екенін түсінемін. Мұны болашақ мансабыңызға салынған инвестиция ретінде қарастырайық. Бастаушы веб-әзірлеушінің орташа жалақысы бұл курсты жұмыстың бірінші айында-ақ ақтауға мүмкіндік береді. Сонымен қатар, бізде артық төлемсіз, ыңғайлы бөліп төлеу мүмкіндігі бар. Бұл бастаманы жеңілдетеді."\n` +
