const handleSendMessage = async (text: string) => {
    setIsLoading(true);
    setError(null);

    const newMessage: Message = { role: Role.User, content: text };
    setMessages((prevMessages) => [...prevMessages, newMessage]);

    try {
      const response = await getBotResponse(text);
      const botMessage: Message = { role: Role.Assistant, content: response };
      setMessages((prevMessages) => [...prevMessages, botMessage]);

      // Payment link detection and product association
      const paymentLinkRegex = /(https?:\/\/[^\s]+)/;
      const match = response.match(paymentLinkRegex);
      if (match) {
        const link = match[0];
        setActivePaymentLink(link);

        // Find the product
        const product = PRODUCTS.find(
          (p) => p.paymentLink === link || p.installmentLink === link
        );
        setProductToConfirm(product || null); // Store the product details
      } else {
        setActivePaymentLink(null);
        setProductToConfirm(null);
      }
    } catch (error: any) {
      setError(error.message || 'An error occurred while sending the message.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleInitiatePurchase = useCallback(() => {
    setIsConfirmationModalOpen(true);
  }, []);

  const handleConfirmPayment = useCallback(() => {
    if (activePaymentLink) {
      window.open(activePaymentLink, '_blank');
      setIsConfirmationModalOpen(false);
      setActivePaymentLink(null);
      setProductToConfirm(null);
      // Add a message to the chat
      const paymentMessage: Message = {
        role: Role.Assistant,
        content: PAYMENT_CONFIRMATION_MESSAGE,
      };
      setMessages((prevMessages) => [...messages, paymentMessage]);
    }
  }, [activePaymentLink, messages]);

  const handleCancelPayment = useCallback(() => {
    setIsConfirmationModalOpen(false);
  }, []);

  useEffect(() => {
    if (activePaymentLink) {
      // Logic to scroll to the bottom when a payment link appears
      chatContainerRef.current?.scrollTo({
        top: chatContainerRef.current.scrollHeight,
        behavior: 'smooth',
      });
    }
  }, [activePaymentLink]);

  return (
    <div className="flex flex-col h-screen bg-gray-900 text-white">
      <ChatHeader />
      <div
        ref={chatContainerRef}
        className="flex-1 overflow-y-auto p-4 space-y-4"
      >
        {messages.map((message, index) => (
          <ChatMessage key={index} message={message} />
        ))}
